from __future__ import annotations

from typing import Dict

import pandas as pd

PRODUCT_DECODE = {"CHK": "CHECKING", "SAV": "SAVINGS", "MMK": "MONEY_MARKET"}


def run(inputs: Dict[str, str]) -> pd.DataFrame:
    accounts = pd.read_csv(inputs["accounts"], dtype=str, keep_default_na=False)
    customers = pd.read_csv(inputs["customers"], dtype=str, keep_default_na=False)

    merged = accounts.merge(
        customers[["customer_id", "last_name"]].drop_duplicates("customer_id"),
        on="customer_id",
        how="left",
    )

    merged["__balance"] = merged["balance"].astype(float)
    merged = merged[merged["__balance"] > 0]

    out = pd.DataFrame({
        "account_id": merged["account_id"],
        "customer_last_name": merged["last_name"].replace("", "UNKNOWN").fillna("UNKNOWN"),
        "product_name": merged["product_code"].map(PRODUCT_DECODE).fillna("OTHER"),
        "balance": merged["__balance"].map(lambda v: "%.2f" % v),
        "activity_month": merged["last_activity_date"].str.slice(0, 7),
    })

    return out.sort_values("account_id", kind="mergesort").reset_index(drop=True)
